const retryWorkspaceTask = `-- name: RetryWorkspaceTask :one
UPDATE tasks AS t
SET status = 'pending', lease_token = '', retry_count = t.retry_count + 1,
    workflow_input = jsonb_set(t.workflow_input, '{execution_token}', to_jsonb($1::text)),
    updated_at = now()
FROM workspaces AS w
WHERE t.workspace_id = w.internal_id
AND t.public_id = $2
AND w.public_id = $3
AND t.status IN ('pending', 'running')
RETURNING t.internal_id, t.public_id, t.workspace_id, t.submitter_user_id, t.billing_account_id, t.service, t.workflow_input, t.status, t.priority, t.retry_count, t.lease_token, t.error_message, t.created_at, t.updated_at, t.started_at, t.completed_at, t.cancelled_at, t.cancelled_by_user_id
`

type RetryWorkspaceTaskParams struct {
	ExecutionToken    string `json:"execution_token"`
	PublicID          string `json:"public_id"`
	WorkspacePublicID string `json:"workspace_public_id"`
}

// RetryWorkspaceTask consumes one retry budget entry: a live task returns
// to pending with retry_count incremented, the lease released (pending rows
// must carry an empty lease_token), and the fresh execution token recorded
// in the workflow_input envelope.
func (q *Queries) RetryWorkspaceTask(ctx context.Context, arg RetryWorkspaceTaskParams) (Task, error) {
	row := q.db.QueryRow(ctx, retryWorkspaceTask, arg.ExecutionToken, arg.PublicID, arg.WorkspacePublicID)
	var i Task
	err := row.Scan(
		&i.InternalID,
		&i.PublicID,
		&i.WorkspaceID,
		&i.SubmitterUserID,
		&i.BillingAccountID,
		&i.Service,
		&i.WorkflowInput,
		&i.Status,
		&i.Priority,
		&i.RetryCount,
		&i.LeaseToken,
		&i.ErrorMessage,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.StartedAt,
		&i.CompletedAt,
		&i.CancelledAt,
		&i.CancelledByUserID,
	)
	return i, err
}
